package com.coraline.tycoon;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.minecraft.core.particles.*;
import net.minecraft.network.chat.Component;

public final class TycoonWorld {
    public static final ResourceKey<Level> KEY=ResourceKey.create(Registries.DIMENSION,ResourceLocation.fromNamespaceAndPath("coraline","personal_other_world"));
    public static UUID owner(ServerPlayer p){return TycoonScope.owner(p);}
    public static TycoonData.Home home(ServerPlayer p){return TycoonData.get(p.server).home(owner(p));}
    public static boolean busy(ServerPlayer p){var h=home(p);return h.state.contains("PendingTransaction")||h.state.contains("PendingPlacement");}
    public static void dirty(ServerPlayer p){TycoonData.get(p.server).setDirty();}
    public static boolean owned(ServerPlayer p,ItemStack item){if(!item.hasTag()||!item.getTag().hasUUID("TycoonOwner")||!owner(p).equals(item.getTag().getUUID("TycoonOwner")))return false;var home=TycoonData.get(p.server).homes.get(owner(p));if(home==null)return false;return !home.state.hasUUID("CapabilityEpoch")||item.getTag().hasUUID("TycoonEpoch")&&home.state.getUUID("CapabilityEpoch").equals(item.getTag().getUUID("TycoonEpoch"));}
    public static boolean currentFurniture(ServerPlayer p,TycoonBlockEntity block){var home=TycoonData.get(p.server).homes.get(owner(p));if(home==null||!owner(p).equals(block.owner))return false;if(!home.state.hasUUID("CapabilityEpoch"))return true;var expected=home.state.getUUID("CapabilityEpoch");if(expected.equals(block.epoch))return true;
        // Only the newly allocated parcel may admit generated fixed furniture.
        // Retired parcel coordinates are never reused by this allocator.
        if(block.epoch==null&&block.getLevel()!=null&&block.getLevel().dimension().equals(KEY)&&TycoonLandscape.owned(home,block.getBlockPos())){block.epoch=expected;block.setChanged();return true;}return false;
    }
    public static ItemStack tagOwned(ServerPlayer p,ItemStack item){var n=item.getOrCreateTag();n.putUUID("TycoonOwner",owner(p));var home=home(p);if(home.state.hasUUID("CapabilityEpoch"))n.putUUID("TycoonEpoch",home.state.getUUID("CapabilityEpoch"));return item;}
    public static ItemStack bound(ServerPlayer p,String id){var s=TycoonContent.stack(id);s.getOrCreateTag().putUUID("TycoonOwner",owner(p));var epoch=home(p).state;if(epoch.hasUUID("CapabilityEpoch"))s.getTag().putUUID("TycoonEpoch",epoch.getUUID("CapabilityEpoch"));if(id.equals("orphanage_phone")){var h=home(p);if(!h.state.hasUUID("PhoneToken"))h.state.putUUID("PhoneToken",UUID.randomUUID());s.getTag().putUUID("PhoneToken",h.state.getUUID("PhoneToken"));}return s;}
    public static boolean validPhone(ServerPlayer p,ItemStack s){var token=home(p).state;return s.is(TycoonContent.PHONE.get())&&owned(p,s)&&s.getTag().hasUUID("PhoneToken")&&token.hasUUID("PhoneToken")&&s.getTag().getUUID("PhoneToken").equals(token.getUUID("PhoneToken"));}
    public static void message(ServerPlayer p,String s){p.displayClientMessage(Component.literal(s),false);}
    public static int room(ServerPlayer p,ItemStack item){int room=0;for(var slot:p.getInventory().items){if(slot.isEmpty())room+=item.getMaxStackSize();else if(ItemStack.isSameItemSameTags(slot,item))room+=Math.max(0,slot.getMaxStackSize()-slot.getCount());}return room;}
    public static boolean deliver(ServerPlayer p,ItemStack item){if(item.isEmpty())return true;if(room(p,item)<item.getCount())return false;boolean added=p.getInventory().add(item.copy());p.getInventory().setChanged();return added;}
    public static void rewardEntrance(ServerPlayer p,long run){if(!owner(p).equals(p.getUUID()))return;var h=home(p);if(run<=h.state.getLong("DoorAwardRun"))return;if(h.entrance()!=null||h.state.hasUUID("DoorToken")&&!h.state.getBoolean("DoorLost")){h.state.putLong("DoorAwardRun",run);dirty(p);return;}if(giveDoor(p,h.state.getBoolean("DoorLost"))){h.state.putLong("DoorAwardRun",run);h.state.remove("DoorLost");dirty(p);}}
    /** A nonce names the one current entrance capability; stale copied items cannot place another. */
    public static boolean giveDoor(ServerPlayer p,boolean replacement){var h=home(p);if(h.entrance()!=null)return false;if(!replacement&&h.state.hasUUID("DoorToken"))return false;var item=bound(p,"special_dimension_little_door");var token=UUID.randomUUID();item.getTag().putUUID("DoorToken",token);if(!deliver(p,item)){message(p,"Free a slot for your reserved Special Dimension Little Door.");return false;}h.state.putUUID("DoorToken",token);dirty(p);return true;}
    public static BlockPos registeredBed(ServerPlayer p){
        var id=owner(p);if(!id.equals(p.getUUID())){var nativeOwner=p.server.getPlayerList().getPlayer(id);var h=home(p);var at=nativeOwner!=null&&nativeOwner.getRespawnDimension().equals(Level.OVERWORLD)?nativeOwner.getRespawnPosition():h.state.contains("RegisteredBed")?BlockPos.of(h.state.getLong("RegisteredBed")):null;if(at==null)return null;var l=p.server.overworld();l.getChunkAt(at);return l.getBlockState(at).getBlock() instanceof BedBlock?at:null;}
        var at=p.getRespawnPosition();if(at==null||!p.getRespawnDimension().equals(Level.OVERWORLD))return null;var l=p.server.overworld();l.getChunkAt(at);return l.getBlockState(at).getBlock() instanceof BedBlock?at:null;
    }
    public static boolean canPlace(ServerPlayer p,String id,BlockPos at,ItemStack stack){
        if(id.equals("special_dimension_little_door")&&!owner(p).equals(p.getUUID()))return false;
        if(id.equals("other_world_supper_table")||id.equals("other_world_fridge"))return owned(p,stack)&&p.serverLevel().dimension()==KEY&&home(p).active()&&TycoonLandscape.owned(home(p),at);
        if(!id.equals("special_dimension_little_door"))return !id.equals("world_work_desk")&&!id.equals("void_foundation")&&owned(p,stack)&&p.level()==p.server.overworld()&&home(p).active();
        var h=home(p);var bed=registeredBed(p);var n=stack.getTag();
        boolean okay=p.level()==p.server.overworld()&&owned(p,stack)&&n.hasUUID("DoorToken")&&h.state.hasUUID("DoorToken")&&n.getUUID("DoorToken").equals(h.state.getUUID("DoorToken"))&&h.entrance()==null&&bed!=null&&bed.distSqr(at)<=Math.pow(TycoonConfig.BED_RADIUS.get(),2)&&safeFeet(p.serverLevel(),at)&&p.serverLevel().getBlockState(at.above()).isAir();
        if(!okay)message(p,"Place your owned Special Door on clear solid ground within "+TycoonConfig.BED_RADIUS.get()+" blocks of your own registered bed. A second entrance cannot be placed.");return okay;
    }
    public static void placed(ServerPlayer p,TycoonBlock block,TycoonBlockEntity be,ItemStack item){var h=home(p);be.epoch=h.state.hasUUID("CapabilityEpoch")?h.state.getUUID("CapabilityEpoch"):null;be.setChanged();if(block==TycoonContent.DOOR.get()){h.state.putLong("Entrance",be.getBlockPos().asLong());var bed=registeredBed(p);if(bed!=null)h.state.putLong("RegisteredBed",bed.asLong());if(h.active())be.getLevel().setBlock(be.getBlockPos(),be.getBlockState().setValue(TycoonBlock.LIT,true),3);h.state.putBoolean("Approved",false);message(p,"Entrance linked. Facilities will be rechecked before new placements.");}else{String key=p.serverLevel().dimension()==KEY?"OtherFurniture":"Furniture";var f=h.state.getCompound(key);f.putString(Long.toString(be.getBlockPos().asLong()),block.kind);h.state.put(key,f);}dirty(p);}
    public static void removed(ServerLevel level,BlockPos pos,TycoonBlockEntity be){if(be.owner==null)return;var h=TycoonData.get(level.getServer()).homes.get(be.owner);if(h==null)return;if(level.dimension().equals(Level.OVERWORLD)){if(pos.equals(h.entrance()))h.state.remove("Entrance");h.state.getCompound("Furniture").remove(Long.toString(pos.asLong()));h.state.putBoolean("Approved",false);}if(level.dimension()==KEY)h.state.getCompound("OtherFurniture").remove(Long.toString(pos.asLong()));TycoonData.get(level.getServer()).setDirty();}
    public static boolean pickup(ServerPlayer p,BlockPos pos){var h=home(p);if(!pos.equals(h.entrance())||p.serverLevel()!=p.server.overworld()||!(p.serverLevel().getBlockEntity(pos) instanceof TycoonBlockEntity be)||!p.getUUID().equals(be.owner))return false;if(p.getInventory().getFreeSlot()<0){message(p,"Free one inventory slot before moving the entrance.");return false;}h.state.remove("Entrance");if(!giveDoor(p,true)){h.state.putLong("Entrance",pos.asLong());return false;}p.serverLevel().removeBlock(pos,false);message(p,"Entrance picked up. Your personal world and residents are preserved.");return true;}
    public static boolean activate(ServerPlayer p,BlockPos pos){var h=home(p);if(h.active()){message(p,"Your personal Other World is already woven. No Weaver consumed.");return false;}if(!pos.equals(h.entrance())||p.serverLevel()!=p.server.overworld()||!(p.serverLevel().getBlockEntity(pos) instanceof TycoonBlockEntity be)||!p.getUUID().equals(be.owner)||!p.getMainHandItem().is(TycoonContent.WEAVER.get()))return false;if(p.server.getLevel(KEY)==null){message(p,"Personal dimension unavailable. Your Weaver was not consumed.");return false;}if(h.state.contains("ActivationStart"))return false;h.state.putLong("ActivationStart",p.server.overworld().getGameTime());h.state.putLong("ActivationDoor",pos.asLong());dirty(p);return true;}
    public static void activationTick(ServerPlayer p){var h=home(p);TycoonCheckpoints.reconcile(p);if(!h.state.contains("ActivationStart"))return;var pos=BlockPos.of(h.state.getLong("ActivationDoor"));var l=p.server.overworld();long age=l.getGameTime()-h.state.getLong("ActivationStart");if(age<0||age>100||p.serverLevel()!=l||p.distanceToSqr(pos.getCenter())>36||!pos.equals(h.entrance())||!p.getMainHandItem().is(TycoonContent.WEAVER.get())){h.state.remove("ActivationStart");if(l.getBlockState(pos).is(TycoonContent.DOOR.get()))l.setBlock(pos,l.getBlockState(pos).setValue(TycoonBlock.LIT,h.active()),3);dirty(p);return;}
        var from=p.getEyePosition().add(p.getLookAngle().scale(.5));var to=pos.getCenter();for(int i=0;i<8;i++){double t=(i+age%4/4.)/8;var v=from.lerp(to,t).add(Math.sin(t*12+age*.3)*.08,Math.sin(t*9+age*.2)*.08,0);l.sendParticles(new DustParticleOptions(new org.joml.Vector3f(.65F,.15F,.95F),.7F),v.x,v.y,v.z,1,0,0,0,0);}if(l.getBlockState(pos).is(TycoonContent.DOOR.get()))l.setBlock(pos,l.getBlockState(pos).setValue(TycoonBlock.LIT,true),3);
        if(age<50)return;h.state.remove("ActivationStart");if(prepare(p)&&TycoonCheckpoints.commit(p)){dirty(p);message(p,"The threads settle. Your personal Other World is ready.");}else{if(l.getBlockState(pos).is(TycoonContent.DOOR.get()))l.setBlock(pos,l.getBlockState(pos).setValue(TycoonBlock.LIT,false),3);message(p,"Activation paused: "+h.state.getString("UnlockBlocker")+". Weaver preserved; no unsafe unlock attempted.");}}
    public static boolean prepare(ServerPlayer p){var h=home(p);var l=p.server.getLevel(KEY);if(l==null)return false;var c=h.center();if(h.state.getBoolean("PlatformBuilt")){for(int x=-4;x<4;x++)for(int z=-4;z<4;z++){var at=c.offset(x,-1,z);l.getChunkAt(at);if(l.getBlockState(at).isAir())l.setBlock(at,TycoonContent.FOUNDATION.get().defaultBlockState(),2);}for(var entry:Map.of(c.offset(-1,0,-1),TycoonContent.DOOR.get(),c.offset(1,0,-1),TycoonContent.DESK.get()).entrySet())if(l.getBlockState(entry.getKey()).isAir())placeOwned(l,entry.getKey(),entry.getValue(),h.owner);return true;}for(int x=-4;x<4;x++)for(int z=-4;z<4;z++)for(int y=-1;y<=2;y++){var at=c.offset(x,y,z);l.getChunkAt(at);if(!l.getBlockState(at).isAir()&&!l.getBlockState(at).is(TycoonContent.FOUNDATION.get())&&!(l.getBlockEntity(at) instanceof TycoonBlockEntity be&&h.owner.equals(be.owner)))return false;}
        for(int x=-4;x<4;x++)for(int z=-4;z<4;z++)l.setBlock(c.offset(x,-1,z),TycoonContent.FOUNDATION.get().defaultBlockState(),2);
        placeOwned(l,c.offset(-1,0,-1),TycoonContent.DOOR.get(),h.owner);placeOwned(l,c.offset(1,0,-1),TycoonContent.DESK.get(),h.owner);h.state.putBoolean("PlatformBuilt",true);dirty(p);return true;}
    public static void placeOwned(ServerLevel l,BlockPos at,Block b,UUID owner){l.setBlock(at,b.defaultBlockState().setValue(TycoonBlock.LIT,true),3);if(l.getBlockEntity(at) instanceof TycoonBlockEntity be){be.owner=owner;be.setChanged();}}
    public static void door(ServerPlayer p,TycoonBlockEntity be){var h=home(p);if(p.serverLevel().dimension().equals(KEY)){if(p.isShiftKeyDown()){message(p,TycoonVisits.sendHome(p));return;}leave(p);return;}if(!be.getBlockPos().equals(h.entrance())||!h.active()){message(p,"Right-click this entrance with a World Weaver to activate it.");return;}enter(p);}
    public static boolean safeFeet(ServerLevel l,BlockPos p){var below=l.getBlockState(p.below());return l.getWorldBorder().isWithinBounds(p)&&!below.is(Blocks.MAGMA_BLOCK)&&!below.is(Blocks.CACTUS)&&!below.is(Blocks.CAMPFIRE)&&!below.is(Blocks.SOUL_CAMPFIRE)&&!l.getBlockState(p).is(Blocks.FIRE)&&!l.getBlockState(p).is(Blocks.SOUL_FIRE)&&below.isFaceSturdy(l,p.below(),Direction.UP)&&l.getBlockState(p).getCollisionShape(l,p).isEmpty()&&l.getBlockState(p.above()).getCollisionShape(l,p.above()).isEmpty()&&l.getFluidState(p).isEmpty()&&l.getFluidState(p.above()).isEmpty();}
    public static BlockPos landing(ServerLevel l,BlockPos center){for(int radius=1;radius<=4;radius++)for(int x=-radius;x<=radius;x++)for(int z=-radius;z<=radius;z++)for(int y:new int[]{0,1,-1}){var p=center.offset(x,y,z);l.getChunkAt(p);if(safeFeet(l,p))return p;}return null;}
    public static void enter(ServerPlayer p){var h=home(p);if(!h.active()||!prepare(p))return;var l=p.server.getLevel(KEY);var at=landing(l,h.center());if(at==null){message(p,"Clear a safe arrival space beside your Work Desk.");if(p.serverLevel()==l){TycoonVisits.sendHome(p);returnOverworld(p,true);}return;}if(!TycoonCollaborationVisits.beforeEnter(p,h))return;p.stopRiding();p.fallDistance=0;p.teleportTo(l,at.getX()+.5,at.getY(),at.getZ()+.5,p.getYRot(),0);}
    public static BlockPos emergencyReturn(ServerLevel l){
        var spawn=l.getSharedSpawnPos();
        // Bounded surface search: never clear a player build to make an exit.
        for(int radius=0;radius<=64;radius+=8)for(int x=-radius;x<=radius;x+=8)for(int z=-radius;z<=radius;z+=8){if(radius>0&&Math.abs(x)!=radius&&Math.abs(z)!=radius)continue;var column=spawn.offset(x,0,z);if(!l.getWorldBorder().isWithinBounds(column))continue;l.getChunkAt(column);var at=l.getHeightmapPos(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,column);if(safeFeet(l,at))return at;}
        // Exceptional all-water/obstructed spawn: add a tiny rescue pad in clear air
        // above the surface. Existing blocks are never replaced or harvested.
        var surface=l.getHeightmapPos(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,spawn);var pad=surface.above(4);if(pad.getY()+3>=l.getMaxBuildHeight())return null;
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<=3;y++)if(!l.getBlockState(pad.offset(x,y,z)).isAir())return null;
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)l.setBlock(pad.offset(x,0,z),Blocks.STONE_BRICKS.defaultBlockState(),3);return pad.above();
    }
    public static void leave(ServerPlayer p){returnOverworld(p,false);}
    private static void returnOverworld(ServerPlayer p,boolean emergency){if(TycoonCollaborationVisits.guest(p)){TycoonCollaborationVisits.leave(p);return;}if(!emergency&&p.serverLevel().dimension()==KEY&&TycoonVisits.blockExit(p))return;var h=home(p);var l=p.server.overworld();var at=h.entrance()==null?null:landing(l,h.entrance());if(at==null&&registeredBed(p)!=null)at=landing(l,registeredBed(p));if(at==null)at=landing(l,l.getSharedSpawnPos());if(at==null)at=emergencyReturn(l);if(at==null){message(p,"No safe surface found at world spawn; remain safely on the platform and contact an operator.");return;}p.stopRiding();p.fallDistance=0;p.teleportTo(l,at.getX()+.5,at.getY(),at.getZ()+.5,p.getYRot(),0);}
}
